import 'dart:math';
import 'dart:ui';

import 'package:flame/components.dart';
import 'package:flame/events.dart';
import 'package:flame/game.dart';

enum BuildingType { port, lumberjack }

/// A geographic island's position/size as generated by the backend - the
/// server is the single source of truth for the map layout, so every
/// player's client renders the same islands at the same coordinates.
class IslandLayout {
  final double centerX;
  final double centerY;
  final double radius;
  final bool isHome;

  const IslandLayout({
    required this.centerX,
    required this.centerY,
    required this.radius,
    required this.isHome,
  });
}

/// An already-built building fetched from the backend on startup, so it can
/// be rendered for whoever loads the app instead of only existing in the
/// session that originally built it.
class BuildingRecord {
  final int id;
  final BuildingType type;
  final double x;
  final double y;
  final Color ownerColor;

  const BuildingRecord({
    required this.id,
    required this.type,
    required this.x,
    required this.y,
    required this.ownerColor,
  });
}

/// Another user's last-known position in this world, as reported by the
/// backend - polled periodically since there's no live push channel yet.
class RemotePlayerRecord {
  final int userId;
  final String username;
  final Color color;
  final double x;
  final double y;

  const RemotePlayerRecord({
    required this.userId,
    required this.username,
    required this.color,
    required this.x,
    required this.y,
  });
}

class IslandGame extends FlameGame {
  static const double islandRadius = 600;
  static const double _worldSeaBoundary = 4500;

  final List<IslandLayout> islandLayout;
  final List<BuildingRecord> existingBuildings;
  final String username;
  final Color playerColor;

  IslandGame({
    required this.islandLayout,
    required this.username,
    required this.playerColor,
    this.existingBuildings = const [],
  });

  late final World islandWorld;
  late final CameraComponent cameraComponent;
  late final IslandComponent homeIsland;
  late final PlayerComponent player;

  final List<IslandComponent> islands = [];
  final List<PortComponent> ports = [];
  final List<BoatComponent> boats = [];
  final List<LumberjackComponent> lumberjacks = [];
  final Map<int, PlayerComponent> _remotePlayers = {};

  /// The island the player is currently standing/walking on.
  late IslandComponent currentPlayerIsland;

  /// Called when the player taps an already-built port, so the Flutter UI
  /// can show that port's menu (a BuildContext is needed for that).
  void Function(PortComponent port)? onPortTapped;

  /// Called when the player taps an already-built lumberjack, so the
  /// Flutter UI can show its menu.
  void Function(LumberjackComponent lumberjack)? onLumberjackTapped;

  /// Called when the player confirms placing a port; the Flutter UI
  /// persists it on the backend and returns its id, or null on failure so
  /// the placement can be rolled back.
  Future<int?> Function(Vector2 position)? onPortBuildRequested;

  /// Called when the player destroys a port; the Flutter UI tells the
  /// backend to forget it and reports whether that succeeded.
  Future<bool> Function(int backendId)? onPortDestroyRequested;

  /// Called when the player confirms placing a lumberjack; the Flutter UI
  /// performs the actual backend call (spending wood) and returns its id,
  /// or null on failure so the placement can be rolled back.
  Future<int?> Function(Vector2 position)? onLumberjackBuildRequested;

  /// Called when the player destroys a lumberjack; the Flutter UI performs
  /// the actual backend call and reports whether it succeeded, so the
  /// removal can be rolled back (the building re-added) if not.
  Future<bool> Function(int backendId)? onLumberjackDestroyRequested;

  /// Called whenever placement mode starts, moves, or ends, so the Flutter
  /// UI (e.g. the Build button label) can stay in sync via setState.
  VoidCallback? onPlacementStateChanged;

  BuildingType? _pendingBuildingType;
  BuildGhostComponent? _ghost;
  late final MapBoundaryComponent _mapBoundary;

  double _minZoom = 0.3;
  double _maxZoom = 3.0;
  double _zoomAtGestureStart = 1;
  bool _hasAppliedInitialZoom = false;

  /// While true, the camera stays wherever the player last dragged it to
  /// instead of re-centering on the player every frame.
  bool _isFreeLooking = false;

  @override
  Color backgroundColor() => const Color(0xFF4FA8D8);

  @override
  Future<void> onLoad() async {
    await super.onLoad();

    islandWorld = World();

    IslandComponent? home;
    for (final layout in islandLayout) {
      final island = await _spawnIsland(
        center: Vector2(layout.centerX, layout.centerY),
        radius: layout.radius,
        treeSpots: _randomTreeSpots(),
      );
      if (layout.isHome) {
        home = island;
      }
    }
    homeIsland = home!;
    currentPlayerIsland = homeIsland;

    for (final record in existingBuildings) {
      await _spawnBuildingFromRecord(record);
    }

    player = PlayerComponent(
      islandRadius: islandRadius,
      username: username,
      ownerColor: playerColor,
    )..position = homeIsland.position.clone();
    await islandWorld.add(player);

    await islandWorld.add(
      WorldInputLayer(onTapAt: _handleWorldTap, onHoverAt: _handleWorldHover),
    );

    _mapBoundary = MapBoundaryComponent(boundaryRadius: _worldSeaBoundary);
    await islandWorld.add(_mapBoundary);

    cameraComponent = CameraComponent(world: islandWorld)
      ..viewfinder.anchor = Anchor.center
      ..viewfinder.position = player.position.clone();

    await addAll([islandWorld, cameraComponent]);

    _fitZoomToScreen();
  }

  @override
  void update(double dt) {
    super.update(dt);
    if (!_isFreeLooking) {
      cameraComponent.viewfinder.position = player.position;
    }
  }

  /// Snaps the camera back to following the player after a free-look pan.
  void recenterOnPlayer() {
    _isFreeLooking = false;
  }

  /// Radius of the sailable sea around the world origin - the minimap uses
  /// it as the extent of the full map.
  double get worldSeaBoundary => _worldSeaBoundary;

  /// Other players currently shown in this world.
  Iterable<PlayerComponent> get remotePlayers => _remotePlayers.values;

  /// The part of the world currently on screen.
  Rect get visibleWorldRect => cameraComponent.visibleWorldRect;

  /// Jumps the camera to [worldPosition] (e.g. from a minimap tap),
  /// entering free-look mode.
  void lookAt(Vector2 worldPosition) {
    _isFreeLooking = true;
    cameraComponent.viewfinder.position = worldPosition;
  }

  void setDebugBoundaryVisible(bool visible) {
    _mapBoundary.visible = visible;
  }

  Future<IslandComponent> _spawnIsland({
    required Vector2 center,
    required double radius,
    required List<Offset> treeSpots,
  }) async {
    final newIsland = IslandComponent(center: center, islandRadius: radius);
    islands.add(newIsland);
    await islandWorld.add(newIsland);
    for (final spot in treeSpots) {
      await islandWorld.add(
        TreeComponent(center: center, relativeOffset: spot, islandRadius: radius),
      );
    }
    return newIsland;
  }

  /// Trees are purely decorative and not part of the shared world state, so
  /// each client is free to scatter its own - only island position/size
  /// comes from the server.
  List<Offset> _randomTreeSpots() {
    final random = Random();
    final treeCount = 2 + random.nextInt(5);
    return List.generate(treeCount, (_) {
      final angle = random.nextDouble() * 2 * pi;
      final distance = 0.15 + random.nextDouble() * 0.45;
      return Offset(cos(angle) * distance, sin(angle) * distance);
    });
  }

  @override
  void onGameResize(Vector2 size) {
    super.onGameResize(size);
    if (isLoaded) {
      _fitZoomToScreen();
    }
  }

  void _fitZoomToScreen() {
    final shortestSide = size.x < size.y ? size.x : size.y;
    final fitZoom = shortestSide / (islandRadius * 2 * 1.3);
    _minZoom = fitZoom * 0.5;
    _maxZoom = fitZoom * 5;

    if (!_hasAppliedInitialZoom) {
      // Only set the zoom on the very first layout. Later calls (e.g. from
      // spurious browser resize/metrics events) should just re-clamp the
      // bounds, not throw away a zoom level the player already chose.
      cameraComponent.viewfinder.zoom = fitZoom;
      _hasAppliedInitialZoom = true;
    } else {
      cameraComponent.viewfinder.zoom =
          cameraComponent.viewfinder.zoom.clamp(_minZoom, _maxZoom);
    }
  }

  void zoomBy(double factor) {
    cameraComponent.viewfinder.zoom =
        (cameraComponent.viewfinder.zoom * factor).clamp(_minZoom, _maxZoom);
  }

  /// Pans the camera by a screen-space [delta] (e.g. from a single-pointer
  /// drag), entering free-look mode.
  void panCameraBy(Vector2 delta) {
    if (delta.length == 0) return;
    _isFreeLooking = true;
    cameraComponent.viewfinder.position -= delta / cameraComponent.viewfinder.zoom;
  }

  /// Called by [WorldInputLayer] when a two-finger pinch/scale gesture begins.
  void handleScaleStart() {
    _zoomAtGestureStart = cameraComponent.viewfinder.zoom;
  }

  /// Called by [WorldInputLayer] as a two-finger pinch/scale gesture
  /// progresses - also pans using the pinch's focal-point movement.
  void handleScaleUpdate(double scale, Vector2 focalPointDelta) {
    cameraComponent.viewfinder.zoom =
        (_zoomAtGestureStart * scale).clamp(_minZoom, _maxZoom);
    panCameraBy(focalPointDelta);
  }

  bool get isPlacingBuilding => _pendingBuildingType != null;

  /// Enters placement mode: a ghost preview of [type] appears and follows
  /// the pointer, glowing green where it's legal to build and red where
  /// it isn't. Tapping on a valid spot confirms the placement.
  void startPlacing(BuildingType type) {
    _pendingBuildingType = type;
    _ghost?.removeFromParent();
    final ghost = BuildGhostComponent(islandRadius: islandRadius)
      ..position = player.position.clone();
    ghost.isValid = _isValidLocation(type, ghost.position);
    _ghost = ghost;
    islandWorld.add(ghost);
    onPlacementStateChanged?.call();
  }

  void cancelPlacing() {
    _pendingBuildingType = null;
    _ghost?.removeFromParent();
    _ghost = null;
    onPlacementStateChanged?.call();
  }

  void _handleWorldHover(Vector2 worldPosition) {
    _updateGhostAt(worldPosition);
  }

  void _updateGhostAt(Vector2 worldPosition) {
    final ghost = _ghost;
    final pending = _pendingBuildingType;
    if (ghost == null || pending == null) return;
    ghost.position = worldPosition;
    ghost.isValid = _isValidLocation(pending, worldPosition);
  }

  /// Called by [BuildGhostComponent] while the player drags it around -
  /// this is how placement works on touch devices, which have no hover.
  void dragGhostBy(Vector2 worldDelta) {
    final ghost = _ghost;
    if (ghost == null) return;
    _updateGhostAt(ghost.position + worldDelta);
  }

  /// Called when the player lets go after dragging the ghost: confirms the
  /// placement if it landed somewhere valid, otherwise just leaves it be so
  /// they can try dragging again.
  void dropGhost() {
    final ghost = _ghost;
    final pending = _pendingBuildingType;
    if (ghost == null || pending == null) return;
    if (ghost.isValid) {
      _confirmPlacement(pending, ghost.position);
    } else {
      onPlacementStateChanged?.call();
    }
  }

  /// The island whose land [worldPosition] falls on, if any.
  IslandComponent? _islandAt(Vector2 worldPosition) {
    for (final candidate in islands) {
      if ((worldPosition - candidate.position).length <= candidate.radius) {
        return candidate;
      }
    }
    return null;
  }

  void _handleWorldTap(Vector2 worldPosition) {
    final pending = _pendingBuildingType;
    if (pending != null) {
      final ghost = _ghost!;
      ghost.position = worldPosition;
      final valid = _isValidLocation(pending, worldPosition);
      ghost.isValid = valid;
      if (valid) {
        _confirmPlacement(pending, worldPosition);
      } else {
        onPlacementStateChanged?.call();
      }
      return;
    }

    final tappedIsland = _islandAt(worldPosition);
    final boardedBoat = player.boardedBoat;

    if (boardedBoat != null) {
      if (tappedIsland != null) {
        _requestLanding(boardedBoat, tappedIsland, worldPosition);
      } else {
        final destination = _clampToSea(worldPosition);
        boardedBoat.moveAlongPath(_seaPathTo(boardedBoat.position, destination));
      }
      return;
    }

    if (tappedIsland == currentPlayerIsland) {
      player.moveTo(tappedIsland!.clampToIsland(worldPosition));
    }
    // Tapping a different island while on foot, or tapping open sea without
    // being aboard a boat, does nothing - you need to sail there first.
  }

  /// Point on [island]'s edge closest to [worldPosition]'s bearing from its
  /// center - i.e. the nearest bit of coastline.
  Vector2 _nearestCoastPoint(IslandComponent island, Vector2 worldPosition) {
    final offset = worldPosition - island.position;
    final direction = offset.length == 0 ? Vector2(1, 0) : offset.normalized();
    return island.position + direction * island.radius;
  }

  /// Called when the player (on foot) taps a boat: walks to the shore right
  /// next to it and hops in automatically on arrival.
  void requestBoard(BoatComponent boat) {
    if (player.boardedBoat != null) return;
    final boardingPoint = _nearestCoastPoint(currentPlayerIsland, boat.position);
    player.moveTo(
      boardingPoint,
      onArrived: () {
        boat.isSelected = true;
        player.boardedBoat = boat;
      },
    );
  }

  /// Called when the player (aboard [boat]) taps a spot on [targetIsland]:
  /// sails the boat to the coastline nearest that spot and only then drops
  /// the player off right next to where the boat actually ends up.
  void _requestLanding(BoatComponent boat, IslandComponent targetIsland, Vector2 tapPosition) {
    final offset = tapPosition - targetIsland.position;
    final direction = offset.length == 0 ? Vector2(1, 0) : offset.normalized();
    final boatDestination = targetIsland.position + direction * (targetIsland.radius * 1.05);
    final landingSpot = targetIsland.position + direction * targetIsland.radius;

    boat.moveAlongPath(
      _seaPathTo(boat.position, boatDestination),
      onArrived: () {
        boat.isSelected = false;
        player.boardedBoat = null;
        player.position = landingSpot;
        currentPlayerIsland = targetIsland;
      },
    );
  }

  /// Keeps [worldPosition] out of every island's land and within the sea's
  /// overall bounds.
  Vector2 _clampToSea(Vector2 worldPosition) {
    var result = worldPosition;
    if (result.length > _worldSeaBoundary) {
      result = result.normalized() * _worldSeaBoundary;
    }
    for (final candidate in islands) {
      final offset = result - candidate.position;
      final minDistance = candidate.radius * 1.05;
      if (offset.length < minDistance) {
        final direction = offset.length == 0 ? Vector2(1, 0) : offset.normalized();
        result = candidate.position + direction * minDistance;
      }
    }
    return result;
  }

  /// A sea route from [start] to [end] that avoids cutting across whichever
  /// island the direct line would cross first: it heads to a safe radius
  /// just off that island's coast, arcs around it, then continues to [end].
  List<Vector2> _seaPathTo(Vector2 start, Vector2 end) {
    IslandComponent? blocker;
    var blockerT = 1.0;

    final segment = end - start;
    final lengthSquared = segment.length2;
    for (final candidate in islands) {
      final t = lengthSquared == 0
          ? 0.0
          : ((candidate.position - start).dot(segment) / lengthSquared).clamp(0.0, 1.0);
      final closestPoint = start + segment * t;
      if ((closestPoint - candidate.position).length < candidate.radius) {
        if (blocker == null || t < blockerT) {
          blocker = candidate;
          blockerT = t;
        }
      }
    }

    if (blocker == null) return [end];

    final center = blocker.position;
    final safeRadius = blocker.radius * 1.15;
    final startAngle = atan2(start.y - center.y, start.x - center.x);
    final endAngle = atan2(end.y - center.y, end.x - center.x);

    var delta = endAngle - startAngle;
    while (delta > pi) {
      delta -= 2 * pi;
    }
    while (delta < -pi) {
      delta += 2 * pi;
    }

    const arcSteps = 6;
    final waypoints = <Vector2>[
      center + Vector2(cos(startAngle), sin(startAngle)) * safeRadius,
    ];
    for (var i = 1; i <= arcSteps; i++) {
      final angle = startAngle + delta * i / arcSteps;
      waypoints.add(center + Vector2(cos(angle), sin(angle)) * safeRadius);
    }
    waypoints.add(end);
    return waypoints;
  }

  bool _isValidLocation(BuildingType type, Vector2 worldPosition) {
    switch (type) {
      case BuildingType.port:
        return currentPlayerIsland.isOnSand(worldPosition);
      case BuildingType.lumberjack:
        return currentPlayerIsland.isOnGrass(worldPosition);
    }
  }

  Future<void> _confirmPlacement(BuildingType type, Vector2 worldPosition) async {
    switch (type) {
      case BuildingType.port:
        final port = PortComponent(
          worldPosition: worldPosition,
          islandRadius: islandRadius,
          ownerColor: playerColor,
        );
        ports.add(port);
        await islandWorld.add(port);
        final id = onPortBuildRequested == null
            ? null
            : await onPortBuildRequested!(worldPosition);
        if (onPortBuildRequested != null && id == null) {
          ports.remove(port);
          port.removeFromParent();
        } else {
          port.backendId = id;
        }
      case BuildingType.lumberjack:
        final lumberjack = LumberjackComponent(
          worldPosition: worldPosition,
          islandRadius: islandRadius,
          ownerColor: playerColor,
        );
        lumberjacks.add(lumberjack);
        await islandWorld.add(lumberjack);
        final id = onLumberjackBuildRequested == null
            ? null
            : await onLumberjackBuildRequested!(worldPosition);
        if (onLumberjackBuildRequested != null && id == null) {
          lumberjacks.remove(lumberjack);
          lumberjack.removeFromParent();
        } else {
          lumberjack.backendId = id;
        }
    }
    cancelPlacing();
  }

  Future<void> destroyPort(PortComponent port) async {
    ports.remove(port);
    port.removeFromParent();

    final backendId = port.backendId;
    if (backendId == null) return;
    final succeeded = await (onPortDestroyRequested?.call(backendId) ?? Future.value(true));
    if (!succeeded) {
      ports.add(port);
      await islandWorld.add(port);
    }
  }

  Future<void> destroyLumberjack(LumberjackComponent lumberjack) async {
    lumberjacks.remove(lumberjack);
    lumberjack.removeFromParent();

    final backendId = lumberjack.backendId;
    if (backendId == null) return;
    final succeeded =
        await (onLumberjackDestroyRequested?.call(backendId) ?? Future.value(true));
    if (!succeeded) {
      // Backend refused/failed the removal - put it back so client and
      // server state stay in sync.
      lumberjacks.add(lumberjack);
      await islandWorld.add(lumberjack);
    }
  }

  Future<void> buildBoatFromPort(PortComponent port) async {
    final hostIsland = _islandAt(port.position) ?? currentPlayerIsland;
    final offset = port.position - hostIsland.position;
    final direction = offset.length == 0 ? Vector2(1, 0) : offset.normalized();
    final spawn = hostIsland.position + direction * (hostIsland.radius * 1.05);
    final boat = BoatComponent(startPosition: spawn, islandRadius: islandRadius);
    boats.add(boat);
    await islandWorld.add(boat);
  }

  Future<void> _spawnBuildingFromRecord(BuildingRecord record) async {
    switch (record.type) {
      case BuildingType.port:
        final port = PortComponent(
          worldPosition: Vector2(record.x, record.y),
          islandRadius: islandRadius,
          ownerColor: record.ownerColor,
        )..backendId = record.id;
        ports.add(port);
        await islandWorld.add(port);
      case BuildingType.lumberjack:
        final lumberjack = LumberjackComponent(
          worldPosition: Vector2(record.x, record.y),
          islandRadius: islandRadius,
          ownerColor: record.ownerColor,
        )..backendId = record.id;
        lumberjacks.add(lumberjack);
        await islandWorld.add(lumberjack);
    }
  }

  /// Reconciles the locally-rendered buildings against the latest list from
  /// the backend: adds anything built by another player since we last
  /// checked, and removes anything someone else has since destroyed.
  Future<void> syncBuildings(List<BuildingRecord> latest) async {
    final latestIds = latest.map((b) => b.id).toSet();

    // Buildings with no backendId yet are still mid-placement (optimistic,
    // awaiting the create call's response) - leave them alone regardless of
    // what the backend currently reports.
    for (final port
        in ports.where((p) => p.backendId != null && !latestIds.contains(p.backendId)).toList()) {
      ports.remove(port);
      port.removeFromParent();
    }
    for (final lumberjack in lumberjacks
        .where((l) => l.backendId != null && !latestIds.contains(l.backendId))
        .toList()) {
      lumberjacks.remove(lumberjack);
      lumberjack.removeFromParent();
    }

    final knownIds = <int>{
      for (final p in ports) if (p.backendId != null) p.backendId!,
      for (final l in lumberjacks) if (l.backendId != null) l.backendId!,
    };
    for (final record in latest) {
      if (knownIds.contains(record.id)) continue;
      await _spawnBuildingFromRecord(record);
    }
  }

  /// Reconciles the locally-rendered other-player markers against the
  /// latest polled positions: adds/updates/removes as players come and go
  /// or move around.
  Future<void> syncRemotePlayers(List<RemotePlayerRecord> latest) async {
    final seenIds = <int>{};
    for (final record in latest) {
      seenIds.add(record.userId);
      final existing = _remotePlayers[record.userId];
      if (existing != null) {
        // Glide toward the newly-reported position instead of snapping to
        // it, so movement reads as continuous walking rather than a
        // teleport every time a poll lands.
        existing.moveTo(Vector2(record.x, record.y));
      } else {
        final remote = PlayerComponent(
          islandRadius: islandRadius,
          username: record.username,
          ownerColor: record.color,
        )..position = Vector2(record.x, record.y);
        _remotePlayers[record.userId] = remote;
        await islandWorld.add(remote);
      }
    }

    final staleIds = _remotePlayers.keys.where((id) => !seenIds.contains(id)).toList();
    for (final id in staleIds) {
      _remotePlayers.remove(id)?.removeFromParent();
    }
  }
}

/// Invisible full-world component whose only job is to translate taps and
/// pointer movement into world coordinates, taking advantage of Flame's
/// automatic camera-aware event coordinates for components mounted inside a
/// [World]. Buildings and units sit at a higher priority so they get first
/// refusal on a tap (and consume it via [TapDownEvent.continuePropagation])
/// before it reaches here.
class WorldInputLayer extends PositionComponent
    with
        TapCallbacks,
        PointerMoveCallbacks,
        DragCallbacks,
        ScaleCallbacks,
        HasGameReference<IslandGame> {
  final void Function(Vector2 worldPosition) onTapAt;
  final void Function(Vector2 worldPosition) onHoverAt;

  WorldInputLayer({required this.onTapAt, required this.onHoverAt})
      : super(
          anchor: Anchor.topLeft,
          position: Vector2.all(-50000),
          size: Vector2.all(100000),
          priority: -100,
        );

  @override
  void onTapDown(TapDownEvent event) {
    super.onTapDown(event);
    onTapAt(position + event.localPosition);
  }

  @override
  void onPointerMove(PointerMoveEvent event) {
    super.onPointerMove(event);
    onHoverAt(position + event.localPosition);
  }

  // Single-pointer (mouse or one-finger touch) panning goes through the
  // drag path - Flame's combined drag/scale recognizer only treats
  // multi-pointer gestures as "scale".
  @override
  void onDragUpdate(DragUpdateEvent event) {
    super.onDragUpdate(event);
    game.panCameraBy(event.localDelta);
  }

  // Two-finger pinch goes through the scale path, which also reports a
  // focal-point delta so panning-while-pinching still works.
  @override
  void onScaleStart(ScaleStartEvent event) {
    super.onScaleStart(event);
    game.handleScaleStart();
  }

  @override
  void onScaleUpdate(ScaleUpdateEvent event) {
    super.onScaleUpdate(event);
    game.handleScaleUpdate(event.scale, event.focalPointDelta);
  }
}

class IslandComponent extends PositionComponent {
  static const double _sandBandFraction = 0.08;

  IslandComponent({required Vector2 center, required double islandRadius})
      : super(
          anchor: Anchor.center,
          position: center,
          size: Vector2.all(islandRadius * 2),
        );

  double get radius => size.x / 2;

  /// Matches the deflate amount used in [render] for the grass oval, so the
  /// visible sand ring and the buildable area are always the same region.
  double get grassRadius => radius - size.x * _sandBandFraction;

  @override
  void render(Canvas canvas) {
    final sandPaint = Paint()..color = const Color(0xFFE8D6A0);
    final grassPaint = Paint()..color = const Color(0xFF7CB342);
    final outer = Rect.fromLTWH(0, 0, size.x, size.y);
    canvas.drawOval(outer, sandPaint);
    final inner = outer.deflate(size.x * _sandBandFraction);
    canvas.drawOval(inner, grassPaint);
  }

  /// Clamps [worldPosition] so it stays within this island's sand oval.
  Vector2 clampToIsland(Vector2 worldPosition) {
    final offset = worldPosition - position;
    if (offset.length <= radius) {
      return worldPosition;
    }
    return position + offset.normalized() * radius;
  }

  /// Whether [worldPosition] falls on the visible sand ring - the only place
  /// a port is allowed to be built.
  bool isOnSand(Vector2 worldPosition) {
    final distance = (worldPosition - position).length;
    return distance >= grassRadius && distance <= radius;
  }

  /// Whether [worldPosition] falls on the inland grass - the only place a
  /// lumberjack is allowed to be built.
  bool isOnGrass(Vector2 worldPosition) {
    final distance = (worldPosition - position).length;
    return distance <= grassRadius;
  }
}

/// Debug-only outline marking the edge of the sailable sea, hidden by
/// default and toggled from the Flutter UI.
class MapBoundaryComponent extends PositionComponent {
  bool visible = false;

  MapBoundaryComponent({required double boundaryRadius})
      : super(
          anchor: Anchor.center,
          position: Vector2.zero(),
          size: Vector2.all(boundaryRadius * 2),
        );

  @override
  void render(Canvas canvas) {
    if (!visible) return;
    final paint = Paint()
      ..color = const Color(0xFFFF00FF)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 24;
    canvas.drawOval(Rect.fromLTWH(0, 0, size.x, size.y), paint);
  }
}

/// Translucent, glowing preview of a building shown while in placement mode.
class BuildGhostComponent extends PositionComponent
    with DragCallbacks, HasGameReference<IslandGame> {
  bool isValid = false;

  BuildGhostComponent({required double islandRadius})
      : super(
          anchor: Anchor.center,
          size: Vector2.all(islandRadius * 0.22),
          priority: 8,
        );

  @override
  void onDragUpdate(DragUpdateEvent event) {
    super.onDragUpdate(event);
    game.dragGhostBy(event.localDelta / game.cameraComponent.viewfinder.zoom);
  }

  @override
  void onDragEnd(DragEndEvent event) {
    super.onDragEnd(event);
    game.dropGhost();
  }

  @override
  void render(Canvas canvas) {
    final glowColor = isValid ? const Color(0xFF4CAF50) : const Color(0xFFF44336);
    final glowPaint = Paint()
      ..color = glowColor.withAlpha(160)
      ..style = PaintingStyle.stroke
      ..strokeWidth = size.x * 0.1
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6);
    canvas.drawCircle(Offset(size.x / 2, size.y / 2), size.x / 2, glowPaint);

    final fillPaint = Paint()..color = glowColor.withAlpha(50);
    canvas.drawCircle(Offset(size.x / 2, size.y / 2), size.x / 2 * 0.85, fillPaint);

    final silhouettePaint = Paint()..color = const Color(0xFF8D6E63).withAlpha(180);
    final rect = Rect.fromLTWH(size.x * 0.25, size.y * 0.4, size.x * 0.5, size.y * 0.4);
    canvas.drawRect(rect, silhouettePaint);
  }
}

class TreeComponent extends PositionComponent {
  TreeComponent({
    required Vector2 center,
    required Offset relativeOffset,
    required double islandRadius,
  }) : super(
          anchor: Anchor.bottomCenter,
          position: center +
              Vector2(relativeOffset.dx * islandRadius, relativeOffset.dy * islandRadius),
          size: Vector2(islandRadius * 0.1, islandRadius * 0.16),
        );

  @override
  void render(Canvas canvas) {
    final trunkPaint = Paint()..color = const Color(0xFF6D4C29);
    final canopyPaint = Paint()..color = const Color(0xFF2E7D32);

    final trunkWidth = size.x * 0.25;
    final trunkHeight = size.y * 0.4;
    final trunkRect = Rect.fromLTWH(
      (size.x - trunkWidth) / 2,
      size.y - trunkHeight,
      trunkWidth,
      trunkHeight,
    );
    canvas.drawRect(trunkRect, trunkPaint);

    final canopyRadius = size.x * 0.5;
    final canopyCenter = Offset(size.x / 2, size.y - trunkHeight - canopyRadius * 0.6);
    canvas.drawCircle(canopyCenter, canopyRadius, canopyPaint);
  }
}

class PlayerComponent extends PositionComponent {
  final double _speed;
  Vector2? _target;
  VoidCallback? _onArrived;

  /// The boat currently carrying the player, if any. While set, the player
  /// rides along with the boat instead of moving independently.
  BoatComponent? boardedBoat;

  final String username;
  final Color ownerColor;

  PlayerComponent({
    required double islandRadius,
    required this.username,
    required this.ownerColor,
  })  : _speed = islandRadius * 0.5,
        super(
          anchor: Anchor.bottomCenter,
          position: Vector2.zero(),
          size: Vector2(islandRadius * 0.06, islandRadius * 0.12),
          priority: 10,
        );

  void moveTo(Vector2 worldTarget, {VoidCallback? onArrived}) {
    _target = worldTarget;
    _onArrived = onArrived;
  }

  @override
  void update(double dt) {
    super.update(dt);

    final boat = boardedBoat;
    if (boat != null) {
      _target = null;
      _onArrived = null;
      position = boat.position + Vector2(0, -boat.size.y * 0.15);
      return;
    }

    final target = _target;
    if (target == null) return;
    final delta = target - position;
    final distance = delta.length;
    final step = _speed * dt;
    if (distance <= step) {
      position = target;
      _target = null;
      final callback = _onArrived;
      _onArrived = null;
      callback?.call();
    } else {
      position += delta.normalized() * step;
    }
  }

  @override
  void render(Canvas canvas) {
    final bodyPaint = Paint()..color = const Color(0xFF3F51B5);
    final headPaint = Paint()..color = const Color(0xFFFFCC80);

    final bodyRect = Rect.fromLTWH(size.x * 0.15, size.y * 0.35, size.x * 0.7, size.y * 0.65);
    canvas.drawRRect(
      RRect.fromRectAndRadius(bodyRect, Radius.circular(size.x * 0.2)),
      bodyPaint,
    );

    final headRadius = size.x * 0.32;
    final headCenter = Offset(size.x / 2, size.y * 0.28);
    canvas.drawCircle(headCenter, headRadius, headPaint);

    _renderNameTag(canvas);
  }

  void _renderNameTag(Canvas canvas) {
    const constraintWidth = 300.0;
    final fontSize = size.x * 0.9;

    final builder = ParagraphBuilder(
      ParagraphStyle(textAlign: TextAlign.center, fontWeight: FontWeight.bold),
    )
      ..pushStyle(TextStyle(
        color: ownerColor,
        fontSize: fontSize,
        fontWeight: FontWeight.bold,
        shadows: const [Shadow(color: Color(0xFF000000), blurRadius: 3, offset: Offset(1, 1))],
      ))
      ..addText(username);
    final paragraph = builder.build()
      ..layout(const ParagraphConstraints(width: constraintWidth));

    canvas.drawParagraph(
      paragraph,
      Offset(size.x / 2 - constraintWidth / 2, -size.y * 0.35 - paragraph.height),
    );
  }
}

/// Draws a small pole-and-pennant above a building in its owner's color, so
/// it's clear at a glance who built what.
void _drawOwnerFlag(Canvas canvas, Vector2 size, Color ownerColor) {
  final poleTop = Offset(size.x * 0.5, -size.y * 0.28);
  final poleBottom = Offset(size.x * 0.5, size.y * 0.05);
  final polePaint = Paint()
    ..color = const Color(0xFF4E342E)
    ..strokeWidth = size.x * 0.03;
  canvas.drawLine(poleBottom, poleTop, polePaint);

  final flagPath = Path()
    ..moveTo(poleTop.dx, poleTop.dy)
    ..lineTo(poleTop.dx + size.x * 0.28, poleTop.dy + size.y * 0.09)
    ..lineTo(poleTop.dx, poleTop.dy + size.y * 0.18)
    ..close();
  canvas.drawPath(flagPath, Paint()..color = ownerColor);
}

class PortComponent extends PositionComponent
    with TapCallbacks, HasGameReference<IslandGame> {
  /// The backing row on the server, once the build call succeeds (or set
  /// directly for buildings loaded from the backend on startup).
  int? backendId;

  final Color ownerColor;

  PortComponent({
    required Vector2 worldPosition,
    required double islandRadius,
    required this.ownerColor,
  }) : super(
          anchor: Anchor.center,
          position: worldPosition,
          size: Vector2.all(islandRadius * 0.22),
          priority: 5,
        );

  @override
  void render(Canvas canvas) {
    final basePaint = Paint()..color = const Color(0xFF8D6E63);
    final roofPaint = Paint()..color = const Color(0xFFD84315);

    final baseRect = Rect.fromLTWH(size.x * 0.15, size.y * 0.35, size.x * 0.7, size.y * 0.55);
    canvas.drawRect(baseRect, basePaint);

    final roofPath = Path()
      ..moveTo(size.x * 0.08, size.y * 0.35)
      ..lineTo(size.x * 0.5, size.y * 0.02)
      ..lineTo(size.x * 0.92, size.y * 0.35)
      ..close();
    canvas.drawPath(roofPath, roofPaint);

    _drawOwnerFlag(canvas, size, ownerColor);
  }

  @override
  void onTapDown(TapDownEvent event) {
    super.onTapDown(event);
    event.continuePropagation = false;
    game.onPortTapped?.call(this);
  }
}

class LumberjackComponent extends PositionComponent
    with TapCallbacks, HasGameReference<IslandGame> {
  /// The backing row on the server, once the build call succeeds (or set
  /// directly for buildings loaded from the backend on startup).
  int? backendId;

  final Color ownerColor;

  LumberjackComponent({
    required Vector2 worldPosition,
    required double islandRadius,
    required this.ownerColor,
  }) : super(
          anchor: Anchor.center,
          position: worldPosition,
          size: Vector2.all(islandRadius * 0.2),
          priority: 5,
        );

  @override
  void render(Canvas canvas) {
    final cabinPaint = Paint()..color = const Color(0xFF5D4037);
    final roofPaint = Paint()..color = const Color(0xFF3E2723);
    final logPaint = Paint()..color = const Color(0xFFA1887F);
    final logEndPaint = Paint()..color = const Color(0xFFD7B899);

    final cabinRect = Rect.fromLTWH(size.x * 0.1, size.y * 0.4, size.x * 0.55, size.y * 0.5);
    canvas.drawRect(cabinRect, cabinPaint);

    final roofPath = Path()
      ..moveTo(size.x * 0.04, size.y * 0.4)
      ..lineTo(size.x * 0.37, size.y * 0.12)
      ..lineTo(size.x * 0.7, size.y * 0.4)
      ..close();
    canvas.drawPath(roofPath, roofPaint);

    // A small stack of cut logs beside the cabin.
    final logRadius = size.x * 0.09;
    final logCenters = [
      Offset(size.x * 0.78, size.y * 0.78),
      Offset(size.x * 0.93, size.y * 0.78),
      Offset(size.x * 0.855, size.y * 0.63),
    ];
    for (final center in logCenters) {
      canvas.drawCircle(center, logRadius, logPaint);
      canvas.drawCircle(center, logRadius * 0.55, logEndPaint);
    }

    _drawOwnerFlag(canvas, size, ownerColor);
  }

  @override
  void onTapDown(TapDownEvent event) {
    super.onTapDown(event);
    event.continuePropagation = false;
    game.onLumberjackTapped?.call(this);
  }
}

class BoatComponent extends PositionComponent
    with TapCallbacks, HasGameReference<IslandGame> {
  final double _speed;
  final List<Vector2> _waypoints = [];
  VoidCallback? _onArrived;
  bool isSelected = false;

  BoatComponent({required Vector2 startPosition, required double islandRadius})
      : _speed = islandRadius * 0.6,
        super(
          anchor: Anchor.center,
          position: startPosition,
          size: Vector2(islandRadius * 0.16, islandRadius * 0.1),
          priority: 5,
        );

  /// Follows a sequence of waypoints in order (see [IslandGame._seaPathTo]),
  /// calling [onArrived] once the final one is reached.
  void moveAlongPath(List<Vector2> waypoints, {VoidCallback? onArrived}) {
    _waypoints
      ..clear()
      ..addAll(waypoints);
    _onArrived = onArrived;
  }

  @override
  void update(double dt) {
    super.update(dt);
    if (_waypoints.isEmpty) return;

    final target = _waypoints.first;
    final delta = target - position;
    final distance = delta.length;
    final step = _speed * dt;
    if (distance <= step) {
      position = target;
      _waypoints.removeAt(0);
      if (_waypoints.isEmpty) {
        final callback = _onArrived;
        _onArrived = null;
        callback?.call();
      }
    } else {
      position += delta.normalized() * step;
    }
  }

  @override
  void render(Canvas canvas) {
    if (isSelected) {
      final ringPaint = Paint()
        ..color = const Color(0xFFFFFFFF)
        ..style = PaintingStyle.stroke
        ..strokeWidth = size.y * 0.08;
      canvas.drawOval(Rect.fromLTWH(0, 0, size.x, size.y).inflate(size.y * 0.15), ringPaint);
    }

    final hullPaint = Paint()..color = const Color(0xFF5D4037);
    final sailPaint = Paint()..color = const Color(0xFFECEFF1);

    final hullRect = Rect.fromLTWH(0, size.y * 0.5, size.x, size.y * 0.5);
    canvas.drawRRect(
      RRect.fromRectAndRadius(hullRect, Radius.circular(size.y * 0.2)),
      hullPaint,
    );

    final sailPath = Path()
      ..moveTo(size.x * 0.5, 0)
      ..lineTo(size.x * 0.5, size.y * 0.55)
      ..lineTo(size.x * 0.15, size.y * 0.55)
      ..close();
    canvas.drawPath(sailPath, sailPaint);
  }

  @override
  void onTapDown(TapDownEvent event) {
    super.onTapDown(event);
    event.continuePropagation = false;
    game.requestBoard(this);
  }
}
